// Package bucket is a token bucket rate limiter.
package bucket

import "time"

// Bucket hands out up to capacity tokens, refilling one per interval.
type Bucket struct {
	capacity int
	refill   time.Duration
	tokens   int
	last     time.Time
}

// New returns a full bucket.
func New(capacity int, refill time.Duration) *Bucket {
	return &Bucket{capacity: capacity, refill: refill, tokens: capacity, last: time.Now()}
}

// Allow takes a token if there is one.
func (b *Bucket) Allow() bool {
	b.restore()
	if b.tokens <= 0 {
		return false
	}
	b.tokens--
	return true
}

// Tokens is how many tokens are available.
func (b *Bucket) Tokens() int {
	b.restore()
	return b.tokens
}

func (b *Bucket) restore() {
	now := time.Now()
	gained := int(now.Sub(b.last) / b.refill)
	if gained > 0 {
		b.tokens += gained
		b.last = now
	}
}

