package bucket

import (
	"testing"
	"time"
)

func TestAllowDrainsThenRefuses(t *testing.T) {
	b := New(2, time.Hour)
	if !b.Allow() || !b.Allow() {
		t.Fatal("a full bucket refused a token")
	}
	if b.Allow() {
		t.Fatal("an empty bucket handed out a token")
	}
	if got := b.Tokens(); got != 0 {
		t.Fatalf("Tokens = %d, want 0", got)
	}
}

