package acceptance_test

import (
	"sync"
	"testing"
	"time"

	"example.com/bucket"
)

func TestConcurrentAllowHandsOutAtMostCapacity(t *testing.T) {
	const capacity = 20
	b := bucket.New(capacity, time.Hour)
	var wg sync.WaitGroup
	var mu sync.Mutex
	granted := 0
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.Allow() {
				mu.Lock()
				granted++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if granted != capacity {
		t.Errorf("granted %d tokens, want exactly %d", granted, capacity)
	}
}

func TestZeroCapacityIsAlwaysEmpty(t *testing.T) {
	b := bucket.New(0, time.Millisecond)
	if b.Allow() {
		t.Error("a zero-capacity bucket handed out a token")
	}
	if got := b.Tokens(); got != 0 {
		t.Errorf("Tokens = %d, want 0", got)
	}
	time.Sleep(20 * time.Millisecond)
	if b.Allow() || b.Tokens() != 0 {
		t.Error("a zero-capacity bucket refilled")
	}
}

func TestIdleBucketNeverExceedsCapacity(t *testing.T) {
	b := bucket.New(2, time.Millisecond)
	b.Allow()
	b.Allow()
	time.Sleep(100 * time.Millisecond)
	if got := b.Tokens(); got != 2 {
		t.Errorf("Tokens after a long idle = %d, want the capacity 2", got)
	}
	if !b.Allow() || !b.Allow() {
		t.Error("a refilled bucket refused a token")
	}
	if b.Allow() {
		t.Error("the bucket held more than its capacity")
	}
}

func TestNonPositiveRefillNeverRestores(t *testing.T) {
	b := bucket.New(1, 0)
	if !b.Allow() {
		t.Fatal("a full bucket refused a token")
	}
	time.Sleep(20 * time.Millisecond)
	if b.Allow() {
		t.Error("a bucket with a zero refill interval restored a token")
	}
}

