// Package bucket is a token bucket rate limiter.
package bucket

import (
	"sync"
	"time"
)

// Bucket hands out up to capacity tokens, refilling one per interval.
// The zero-capacity bucket is always empty, and a non-positive refill
// means tokens are never restored.
type Bucket struct {
	mu       sync.Mutex
	capacity int
	refill   time.Duration
	tokens   int
	last     time.Time
}

// New returns a full bucket.
func New(capacity int, refill time.Duration) *Bucket {
	if capacity < 0 {
		capacity = 0
	}
	return &Bucket{capacity: capacity, refill: refill, tokens: capacity, last: time.Now()}
}

// Allow takes a token if there is one.
func (b *Bucket) Allow() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.restoreLocked(time.Now())
	if b.tokens <= 0 {
		return false
	}
	b.tokens--
	return true
}

// Tokens is how many tokens are available.
func (b *Bucket) Tokens() int {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.restoreLocked(time.Now())
	return b.tokens
}

// restoreLocked credits whole refill intervals since last, and never
// lets the bucket hold more than its capacity.
func (b *Bucket) restoreLocked(now time.Time) {
	if b.refill <= 0 || b.capacity <= 0 {
		return
	}
	elapsed := now.Sub(b.last)
	if elapsed < b.refill {
		return
	}
	gained := int(elapsed / b.refill)
	b.tokens += gained
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	b.last = b.last.Add(time.Duration(gained) * b.refill)
}
